#include <stdio.h>
#include <string.h>

/* Returns 1 if str is generated by S -> 0S0 | 1S1 | 0 | 1 | epsilon */
int belongs(const char *str) {
    int len = (int)strlen(str);

    /* Only the terminals 0 and 1 exist in this grammar */
    for (int i = 0; i < len; i++)
        if (str[i] != '0' && str[i] != '1') return 0;

    /* Each 0S0 / 1S1 step matches the outermost remaining pair */
    for (int i = 0, j = len - 1; i < j; i++, j--)
        if (str[i] != str[j]) return 0;

    return 1;   /* the middle is S -> 0 | 1 | epsilon */
}

/* Prints the leftmost derivation of an accepted string */
void print_derivation(const char *str) {
    int len  = (int)strlen(str);
    int half = len / 2;                  /* number of 0S0 / 1S1 steps */

    printf("\nDerivation:\n");
    printf("S");

    for (int k = 1; k <= half; k++) {
        printf("\n  => %.*sS%s", k, str, str + len - k);
        printf("          (S -> %cS%c)", str[k - 1], str[k - 1]);
    }

    if (len % 2 == 1) {                  /* odd length: middle symbol */
        printf("\n  => %s", str);
        printf("          (S -> %c)\n", str[half]);
    } else {                             /* even length: nothing in the middle */
        if (len == 0)
            printf("\n  => epsilon");
        else
            printf("\n  => %s", str);
        printf("          (S -> epsilon)\n");
    }
}

int main(void) {
    char str[100];

    printf("Grammar:  S -> 0S0 | 1S1 | 0 | 1 | epsilon\n\n");
    printf("Enter a string (press Enter alone for the empty string): ");

    if (fgets(str, sizeof(str), stdin) == NULL) str[0] = '\0';
    str[strcspn(str, "\r\n")] = '\0';    /* strip the newline */

    if (belongs(str)) {
        printf("\nString \"%s\" BELONGS to the grammar\n", str);
        print_derivation(str);
    } else {
        printf("\nString \"%s\" does NOT belong to the grammar\n", str);
    }

    return 0;
}
